def _max_depth_of_nested_paren(paren_string, current_depth, max_depth):
    current_depth += 1
    paren_level = 0
    if paren_string.count('(') != paren_string.count(')'):
        return _max_depth_of_nested_paren(paren_string[1:], current_depth, max_depth)
