def sign_of_number(number: float) -> float:
    """ Returns the sign of the number. 1 for positive, -1 for negative,
    0 for zero.
    >>> sign_of_number(0.5)
    1.0
    >>> sign_of_number(-3.1)
    -1.0
    >>> sign_of_number(-0.0)
    0.0
    """
    if number == 0:
        return 0.0
