def max_depth(nested_string: str) -> int:
    """ Helper function to find the maximum depth of a nested string.
    """
    depth, level = 0, 0
    for c in nested_string:
        if c == '(':
            level += 1
        elif c == ')':
            level -= 1
        depth = max(depth, level)
    return depth

