def check_prime(number: int) -> bool:
    """Return True if number is prime else False.
    >>> check_prime(42)
    False
    >>> check_prime(47)
    True
    """
    if number <= 1:
        return False
    elif number == 2:
        return True
    elif number % 2 == 0:
        return False
