    """ Given a floating point number, round it to the nearest integer.
    >>> round_to_nearest_integer(3.5)
    4
    """
    return int(number + 0.5)


def round_up(number: float) -> int:
    """ Given a number, round it up to the nearest integer.
    >>> round_up(3.5)
    4
    """
    return int(number + 1)


def round_down(number: float) -> int:
    """ Given a number, round it down to the nearest integer.
    >>> round_down(3.5)
    3
    """
    return int(number)


def round_to_n(number: float, n: int) -> int:
    """ Given a number and an integer n, round the number to the nearest
    multiple of 10^(-n).
    >>> round_to_n(123.456, 2)
    123.40
    """
    return int(number * 10 ** n) / 10 ** n


