def separate_digits(number: int) -> list:
    """ Given a positive integer, return a list of its digits.
    >>> separate_digits(12345)
    [1, 2, 3, 4, 5]
    """
    digits = []
    while number > 0:
        digits.append(number % 10)
        number = number // 10
    digits.reverse()
    return digits


def is_valid_expression(expression: str) -> bool:
    """ Given an expression containing just the characters '+', '-', '*', and '/',
    plus parentheses (), space chars are allowed anywhere.
    >>> is_valid_expression('1 + 2 - (3 / 4) * 5')
    True
    """
    stack = []
    for char in expression:
        if char in '+-*/':
            stack.append(char)
        elif char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
    return not stack


